import{_ as t,o as s,c as a,a0 as r}from"./chunks/framework.BL79I5mR.js";const n="/docs/assets/crosswalk-navigation.BcLb1isc.png",i="/docs/assets/progress-bar.D0mAdZKC.png",l="/docs/assets/main-alignment-screen.bIRd4E6n.png",c="/docs/assets/action-buttons.DehElUO9.png",m="/docs/assets/relationship-add-button.l-Uc2EeU.png",p="/docs/assets/relationship-type-selection.QS52Ikak.png",h="/docs/assets/target-competency-selection.kb_wjzZ4.png",g="/docs/assets/apply-alignments-button.CaKGVAeR.png",w="/docs/assets/alignment-change-tally.CxUzZs7S.png",o="/docs/assets/alignment-bubble.rVoBavbh.png",k="/docs/assets/target-competency-removal.DYWI5qN0.png",d="/docs/assets/apply-alignment-bubble.DjbFpKuz.png",u="/docs/assets/alignment-removing-one.Bk4Chjov.png",f="/docs/assets/alignment-save-and-review._f40r1yO.png",b="/docs/assets/alignment-summary.DeQ7jlYk.png",C="/docs/assets/framework-application-selection.8mMyPGzt.png",y="/docs/assets/continue-editing.mBtFUAsE.png",v="/docs/assets/save-alignments.D7xErM48.png",B=JSON.parse('{"title":"Framework Crosswalk Tool","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/crosswalk-tool/index.md","filePath":"authoring/crosswalk-tool/README.md"}'),_={name:"authoring/crosswalk-tool/index.md"};function A(T,e,F,S,x,R){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="framework-crosswalk-tool" tabindex="-1">Framework Crosswalk Tool <a class="header-anchor" href="#framework-crosswalk-tool" aria-label="Permalink to &quot;Framework Crosswalk Tool&quot;">​</a></h1><p>The Framework Crosswalk Tool can be used to create relationships across two separate frameworks.</p><p>In order to apply any relationships created with the crosswalk tool, at least one of the frameworks initially selected in the tool wizard must be owned and editable by the logged in user.</p><h2 id="accessing-the-framework-crosswalk-tool" tabindex="-1">Accessing the Framework Crosswalk Tool <a class="header-anchor" href="#accessing-the-framework-crosswalk-tool" aria-label="Permalink to &quot;Accessing the Framework Crosswalk Tool&quot;">​</a></h2><p>The Framework Crosswalk Tool can be accessed at any time by selecting the crosswalk frameworks icon under the <em><strong>competencies &amp; frameworks</strong></em> category in the navigation menu.</p><p><img src="'+n+'" alt="CAT Competency Framework Management - Crosswalk Frameworks Navigation"></p><h2 id="crosswalk-overview" tabindex="-1">Crosswalk Overview <a class="header-anchor" href="#crosswalk-overview" aria-label="Permalink to &quot;Crosswalk Overview&quot;">​</a></h2><p>Framework crosswalking is comprised of four steps:</p><ol><li><strong>Select Source</strong><ul><li>Selection of the source framework</li><li>The selection for the source framework is limited to frameworks that are owned and editable by the current user.</li><li>The source framework also defines the relationship types available for the crosswalk by determining the applied configuration of that framework.  If there is no explicit configuration applied to the selected framework, the relationships available for the crosswalk are determined by the selected browser default configuration or the instance default configuration.</li></ul></li><li><strong>Select Target</strong><ul><li>Selection of the target framework</li></ul></li><li><strong>Align Frameworks</strong><ul><li>Creation of the relationships between the competencies of the two frameworks</li></ul></li><li><strong>Save &amp; Review</strong><ul><li>Review of created relationships, determination of where the relationships will reside (one or both of the chosen frameworks), and the saving of the relationships</li></ul></li></ol><p>The current step will be highlighted by the progress bar at the top of the crosswalk tool screen.</p><p><img src="'+i+'" alt="CAT Crosswalk Frameworks - Progress Bar"></p><h2 id="aligning-framework-competencies" tabindex="-1">Aligning Framework Competencies <a class="header-anchor" href="#aligning-framework-competencies" aria-label="Permalink to &quot;Aligning Framework Competencies&quot;">​</a></h2><p>After selecting the source and target frameworks, the selected frameworks will be displayed in side by side panes. Any existing relationships between the two frameworks will be indicated by orange bubbles underneath the corresponding competency in the source framework pane.</p><p><img src="'+l+'" alt="CAT Crosswalk Frameworks - Main Alignment Screen"></p><p>At the top of each framework pane are four action buttons. Clicking these action buttons will affect only the framework view in the corresponding pane.</p><ul><li><strong>show aligned only</strong> - show only competencies that have alignments to competencies in the other framework</li><li><strong>show unaligned only</strong> - show only competencies that do not have alignments to competencies in the other framework</li><li><strong>show all (<em>default</em>)</strong> - show all competencies regardless of existing alignments</li><li><strong>change framework</strong> - change the source/target framework <ul><li>Selecting this action will remove all unsaved alignments from the current crosswalk session</li></ul></li></ul><p><img src="'+c+'" alt="CAT Crosswalk Frameworks - Crosswalk Action Buttons"></p><h3 id="adding-a-crosswalk-relationship-alignment" tabindex="-1">Adding a Crosswalk Relationship/Alignment <a class="header-anchor" href="#adding-a-crosswalk-relationship-alignment" aria-label="Permalink to &quot;Adding a Crosswalk Relationship/Alignment&quot;">​</a></h3><p>To begin adding a relationship between the competencies within the frameworks, hover over the appropriate competency in the source framework pane and click the <em><strong>add</strong></em> button.</p><p><img src="'+m+'" alt="CAT Crosswalk Frameworks - Relationship Add Button"></p><p>Select the desired relationship type from the dropdown.</p><p><img src="'+p+'" alt="CAT Crosswalk Frameworks - Relationship Type Selection"></p><p>Once a relationship type has been selected, click the <em><strong>+ button</strong></em> to the right of each competency in the target framework pane you wish to apply the relationship. When clicked, the <em><strong>+ button</strong></em> will transition into a checkmark. Clicking on this checkmark will remove the relationship.</p><p><img src="'+h+'" alt="CAT Crosswalk Frameworks - Target Competency Selection"></p><p>After selecting the desired competencies, click the apply alignments button.  Once applied, you will notice a running tally of added and removed alignments under the crosswalk progress bar.</p><p><img src="'+g+'" alt="CAT Crosswalk Frameworks - Apply Alignments Button."></p><p><img src="'+w+'" alt="CAT Crosswalk Frameworks - Alignment Change Tally"></p><p>The alignment tally will keep track of both the addition of new alignments and the removal of alignments created in previous crosswalk sessions.</p><p>Once applied, alignments can be quickly accessed by clicking on the corresponding alignment bubble underneath the source competency.</p><p><img src="'+o+'" alt="CAT Crosswalk Frameworks - Alignment Bubble"></p><h3 id="removing-a-crosswalk-relationship-alignment" tabindex="-1">Removing a Crosswalk Relationship/Alignment <a class="header-anchor" href="#removing-a-crosswalk-relationship-alignment" aria-label="Permalink to &quot;Removing a Crosswalk Relationship/Alignment&quot;">​</a></h3><p>To remove an existing relationship click on the corresponding alignment bubble underneath the source competency.</p><p><img src="'+o+'" alt="CAT Crosswalk Frameworks - Alignment Bubble"></p><p>In the target pane, click on the checkmark icon to the right of the competency you wish to remove from the relationship. When clicked, the checkmark icon will transition into a + button.</p><p><img src="'+k+'" alt="CAT Crosswalk Frameworks - Target Competency Removal"></p><p>After removing the undesired competencies, click the apply alignments button. Once applied, you will notice a running tally of added and removed alignments under the crosswalk progress bar.</p><p><img src="'+d+'" alt="CAT Crosswalk Frameworks - Apply Alignments Button."></p><p><img src="'+u+'" alt="CAT Crosswalk Frameworks - Alignment Change Tally"></p><h2 id="crosswalk-review-and-save" tabindex="-1">Crosswalk Review and Save <a class="header-anchor" href="#crosswalk-review-and-save" aria-label="Permalink to &quot;Crosswalk Review and Save&quot;">​</a></h2><p>To save all changes made during the crosswalk session to the repository, click on the <em><strong>save &amp; review</strong></em> button.</p><p><img src="'+f+'" alt="CAT Crosswalk Frameworks - Save &amp; Review"></p><p>The summary screen will be displayed detailing the overall alignment changes between the two frameworks and the framework application selector. By default, all owned or editable frameworks used in the crosswalk will be checked. A check mark next the framework means all alignment/relationship changes made will be applied to that framework.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>You may only apply alignment changes to frameworks that you own or can edit.</p></div><p><img src="'+b+'" alt="CAT Crosswalk Frameworks - Crosswalk Alignment Summary"></p><p><img src="'+C+'" alt="CAT Crosswalk Frameworks - Framework Application Selection"></p><p>If you wish to make further changes to the alignments, click on the <em><strong>continue editing</strong></em> button.</p><p><img src="'+y+'" alt="CAT Crosswalk Frameworks - Continue Editing Button"></p><p>When you are satisfied with your changes, click on the <em><strong>save alignments</strong></em> button.</p><p><img src="'+v+'" alt="CAT Crosswalk Frameworks - Save Alignments Button"></p>',49)])])}const P=t(_,[["render",A]]);export{B as __pageData,P as default};
